import{_ as t,o as n,c as s,a5 as e}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"分支","description":"","frontmatter":{"title":"分支","order":4},"headers":[],"relativePath":"tc/2.4/tutorial/script/branch.md","filePath":"tc/2.4/tutorial/script/branch.md","lastUpdated":1788455378000}'),p={name:"tc/2.4/tutorial/script/branch.md"};function o(i,a,l,r,c,d){return n(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="分支" tabindex="-1">分支 <a class="header-anchor" href="#分支" aria-label="Permalink to &quot;分支&quot;">​</a></h1><h2 id="功能描述" tabindex="-1">功能描述 <a class="header-anchor" href="#功能描述" aria-label="Permalink to &quot;功能描述&quot;">​</a></h2><p>分支是一種用於組織腳本內容的方式。透過分支，可以方便地管理和呼叫腳本中的不同部分，用於實作複雜的跳轉邏輯。此功能通常搭配選項使用。</p><p>可以將標籤理解為腳本中的「書籤」。透過標籤可以快速定位到腳本中的特定位置。由標籤和縮排包裹的內容即為標籤內容。這部分腳本內容在執行目前標籤對話時會被加入對話列表，否則只會儲存在標籤對話中，不會觸發播放。</p><p>分支不可巢狀使用，分支的縮排層級必須與對話的縮排層級一致，否則會導致無法正常識別。以下是錯誤範例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 錯誤範例</span></span>
<span class="line"><span>branch drink_water</span></span>
<span class="line"><span>    &quot;kona&quot; &quot;我想喝水&quot;</span></span>
<span class="line"><span>        branch eat_cake</span></span>
<span class="line"><span>            &quot;kona&quot; &quot;我想吃蛋糕&quot;</span></span>
<span class="line"><span>branch drink_tea</span></span>
<span class="line"><span>    &quot;kona&quot; &quot;我想喝茶&quot;</span></span></code></pre></div><h2 id="語法結構" tabindex="-1">語法結構 <a class="header-anchor" href="#語法結構" aria-label="Permalink to &quot;語法結構&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>branch [標籤ID]</span></span>
<span class="line"><span>    [腳本內容]</span></span></code></pre></div><h2 id="參數詳解" tabindex="-1">參數詳解 <a class="header-anchor" href="#參數詳解" aria-label="Permalink to &quot;參數詳解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>參數</th><th>必需</th><th>範例</th><th>說明</th></tr></thead><tbody><tr><td>標籤ID</td><td>是</td><td><code>drink_water</code></td><td>標籤識別符</td></tr></tbody></table><h2 id="範例" tabindex="-1">範例 <a class="header-anchor" href="#範例" aria-label="Permalink to &quot;範例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>branch drink_water</span></span>
<span class="line"><span>    &quot;kona&quot; &quot;我想喝水&quot;</span></span>
<span class="line"><span>branch drink_tea</span></span>
<span class="line"><span>    &quot;kona&quot; &quot;我想喝茶&quot;</span></span></code></pre></div>`,12)])])}const b=t(p,[["render",o]]);export{u as __pageData,b as default};
